    scratch = scratch >>> 48
    scratch = scratch ||| v <<< 3
    v = value_seed >>> 32 &&& 0xFFFFFFFF
    sc8 = scratch
    scratch = scratch >>> 32
    scratch = scratch ||| v <<< 3
    v = value_seed >>> 64 &&& 0xFFFFFFFF
    sc9 = scratch
    scratch = scratch >>> 32
