  @spec read_wide_probe_bits(binary(), non_neg_integer()) ::
          {:ok, Ludicrous.WideProbe.t(), non_neg_integer()} | :error
  def read_wide_probe_bits(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    try do
