      w = v
      rv = rdw(data, 32, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      rv = rdw(data, 64, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 64
      rv = rdw(data, 96, 49)
      v = rv &&& 0xFFFFFFFF
