      v_bias = v - 1000
      rv = rdw(data, 275, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, 307, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      rv = rdw(data, 339, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 64
      rv = rd(data, 371, 32)
      v = rv
      w = w ||| v <<< 96
      v_seed = w

      value = %Ludicrous.WideProbe{
        entity_id: v_entity_id,
        energy: v_energy,
        flux: v_flux,
        bias: v_bias,
        seed: v_seed
